import subprocess, time, re
def start(cmd, w=120, h=40):
    subprocess.run(["tmux","kill-session","-t","test"], stderr=subprocess.DEVNULL); time.sleep(0.3)
    subprocess.run(["tmux","new-session","-d","-s","test","-x",str(w),"-y",str(h)])
    subprocess.run(["tmux","send-keys","-t","test",cmd,"Enter"]); time.sleep(0.9)
def send(*ks):
    for k in ks: subprocess.run(["tmux","send-keys","-t","test",k])
    time.sleep(0.35)
def sendl(s):
    subprocess.run(["tmux","send-keys","-t","test","-l",s]); time.sleep(0.4)
def lines():
    return subprocess.check_output(["tmux","capture-pane","-t","test","-p"]).decode().split("\n")
def esc():
    return subprocess.check_output(["tmux","capture-pane","-t","test","-p","-e"]).decode().split("\n")
def footer():
    L=lines(); return L[-2] if L and L[-1]=="" else (L[-1] if L else "")
    # capture-pane without -? last lines: actually height lines, footer is index h-1
def cap(a=0,b=None):
    L=lines()
    if b is None: b=len(L)
    for i in range(a,min(b,len(L))): print(f"{i:02d}|{L[i].rstrip()}|")
    print("CUR",cur())
def cur():
    return subprocess.check_output(["tmux","display-message","-t","test","-p","#{cursor_x},#{cursor_y}"]).decode().strip()
def results():
    L=lines(); return sorted([l[:36].strip().strip("│").strip() for l in L if "(" in l[:36] and "│" in l[:36]])
def leftline(i): return lines()[i][:36]
def preview():
    # returns preview segments (strip borders) for lines that are non-empty
    out=[]
    for l in lines():
        if len(l)>38:
            seg=l[37:].rstrip()
            seg=seg.rstrip("│").rstrip()
            if seg.strip(" ─╮╯"): out.append(seg)
    return out
