use regex::Regex;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}

impl SearchMode {
    pub fn label(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
    pub fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    pub fn label(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
    pub fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
}

/// Regex used for the actual text replacement (whole-file and line replace).
/// Note: the Regex search mode intentionally behaves like Simple here,
/// matching the reference behaviour.
pub fn replacement_regex(search_text: &str, mode: SearchMode) -> Option<Regex> {
    let escaped = regex::escape(search_text);
    let pattern = match mode {
        SearchMode::Simple | SearchMode::Regex => format!("(?i){escaped}"),
        SearchMode::MatchCase => escaped,
        SearchMode::MatchWholeWord => format!(r"(?i)\b{escaped}\b"),
        SearchMode::MatchCaseWholeWord => format!(r"\b{escaped}\b"),
    };
    Regex::new(&pattern).ok()
}

pub fn preserve_case(matched: &str, replace: &str) -> String {
    let has_upper = matched.chars().any(|c| c.is_uppercase());
    let has_lower = matched.chars().any(|c| c.is_lowercase());
    if has_upper && !has_lower {
        replace.to_uppercase()
    } else if matched.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
        let lower = replace.to_lowercase();
        let mut chars = lower.chars();
        match chars.next() {
            Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
            None => lower,
        }
    } else {
        replace.to_lowercase()
    }
}

/// Apply replacement to `text` (used for whole file content and single lines).
pub fn do_replace(
    text: &str,
    search_text: &str,
    replace_text: &str,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
) -> String {
    let Some(re) = replacement_regex(search_text, search_mode) else {
        return text.to_string();
    };
    match replace_mode {
        ReplaceMode::Simple => re.replace_all(text, regex::NoExpand(replace_text)).to_string(),
        ReplaceMode::PreserveCase => re
            .replace_all(text, |caps: &regex::Captures| {
                preserve_case(caps.get(0).map(|m| m.as_str()).unwrap_or(""), replace_text)
            })
            .to_string(),
        ReplaceMode::DeleteLine => text.to_string(),
    }
}
