use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use unicode_width::UnicodeWidthChar;

/// A single-line text input replicating the behaviour of the editor used by
/// the reference (tui-input style requests and semantics).
#[derive(Clone, Default)]
pub struct Input {
    value: String,
    /// cursor as char index into value
    cursor: usize,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Request {
    InsertChar(char),
    DeletePrevChar,
    DeleteNextChar,
    DeletePrevWord,
    DeleteNextWord,
    DeleteLine,
    DeleteTillStart,
    DeleteTillEnd,
    GoToPrevChar,
    GoToNextChar,
    GoToPrevWord,
    GoToNextWord,
    GoToStart,
    GoToEnd,
}

impl Request {
    pub fn is_edit(self) -> bool {
        !matches!(
            self,
            Request::GoToPrevChar
                | Request::GoToNextChar
                | Request::GoToPrevWord
                | Request::GoToNextWord
                | Request::GoToStart
                | Request::GoToEnd
        )
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
}

impl Input {
    pub fn new(value: String) -> Self {
        let cursor = value.chars().count();
        Self { value, cursor }
    }
    pub fn value(&self) -> &str {
        &self.value
    }
    pub fn reset(&mut self) {
        self.value.clear();
        self.cursor = 0;
    }
    fn chars(&self) -> Vec<char> {
        self.value.chars().collect()
    }
    fn byte_idx(&self, char_idx: usize) -> usize {
        self.value
            .char_indices()
            .nth(char_idx)
            .map(|(i, _)| i)
            .unwrap_or(self.value.len())
    }
    pub fn visual_cursor(&self) -> usize {
        self.value
            .chars()
            .take(self.cursor)
            .map(|c| UnicodeWidthChar::width(c).unwrap_or(0))
            .sum()
    }
    pub fn visual_scroll(&self, width: usize) -> usize {
        let vc = self.visual_cursor();
        if width == 0 {
            return vc;
        }
        vc.saturating_sub(width - 1)
    }

    fn prev_word_start(&self) -> usize {
        let chars = self.chars();
        let mut i = self.cursor;
        // skip non-word chars, then word chars
        while i > 0 && !is_word_char(chars[i - 1]) {
            i -= 1;
        }
        while i > 0 && is_word_char(chars[i - 1]) {
            i -= 1;
        }
        i
    }
    fn next_word_start(&self) -> usize {
        let chars = self.chars();
        let n = chars.len();
        let mut i = self.cursor;
        while i < n && is_word_char(chars[i]) {
            i += 1;
        }
        while i < n && !is_word_char(chars[i]) {
            i += 1;
        }
        i
    }

    /// Execute a request. Returns true if this request may have modified the
    /// value (used to trigger live search, mirroring the reference: edit
    /// requests trigger even when they don't change anything).
    pub fn execute(&mut self, req: Request) -> bool {
        match req {
            Request::InsertChar(c) => {
                let idx = self.byte_idx(self.cursor);
                self.value.insert(idx, c);
                self.cursor += 1;
            }
            Request::DeletePrevChar => {
                if self.cursor > 0 {
                    let idx = self.byte_idx(self.cursor - 1);
                    self.value.remove(idx);
                    self.cursor -= 1;
                }
            }
            Request::DeleteNextChar => {
                let idx = self.byte_idx(self.cursor);
                if idx < self.value.len() {
                    self.value.remove(idx);
                }
            }
            Request::DeletePrevWord => {
                let start = self.prev_word_start();
                if start < self.cursor {
                    let a = self.byte_idx(start);
                    let b = self.byte_idx(self.cursor);
                    self.value.drain(a..b);
                    self.cursor = start;
                }
            }
            Request::DeleteNextWord => {
                let end = self.next_word_start();
                if end > self.cursor {
                    let a = self.byte_idx(self.cursor);
                    let b = self.byte_idx(end);
                    self.value.drain(a..b);
                }
            }
            Request::DeleteLine => {
                self.value.clear();
                self.cursor = 0;
            }
            Request::DeleteTillStart => {
                let b = self.byte_idx(self.cursor);
                self.value.drain(..b);
                self.cursor = 0;
            }
            Request::DeleteTillEnd => {
                let a = self.byte_idx(self.cursor);
                self.value.truncate(a);
            }
            Request::GoToPrevChar => {
                self.cursor = self.cursor.saturating_sub(1);
            }
            Request::GoToNextChar => {
                let n = self.value.chars().count();
                if self.cursor < n {
                    self.cursor += 1;
                }
            }
            Request::GoToPrevWord => {
                self.cursor = self.prev_word_start();
            }
            Request::GoToNextWord => {
                self.cursor = self.next_word_start();
            }
            Request::GoToStart => self.cursor = 0,
            Request::GoToEnd => {
                self.cursor = self.value.chars().count();
            }
        }
        req.is_edit()
    }

    /// Map a key event to an input request (tui-input crossterm backend
    /// mapping as observed).
    pub fn to_request(key: &KeyEvent) -> Option<Request> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        Some(match key.code {
            KeyCode::Char('w') if ctrl => Request::DeletePrevWord,
            KeyCode::Char('u') if ctrl => Request::DeleteLine,
            KeyCode::Char('k') if ctrl => Request::DeleteTillEnd,
            KeyCode::Char('h') if ctrl => Request::DeletePrevChar,
            KeyCode::Char('a') if ctrl => Request::GoToStart,
            KeyCode::Char('e') if ctrl => Request::GoToEnd,
            KeyCode::Char('f') if ctrl => Request::GoToNextChar,
            KeyCode::Char('b') if ctrl => Request::GoToPrevChar,
            KeyCode::Char(c) if !ctrl && !alt => Request::InsertChar(c),
            KeyCode::Backspace if alt => Request::DeletePrevWord,
            KeyCode::Backspace => Request::DeletePrevChar,
            KeyCode::Delete if ctrl => Request::DeleteNextWord,
            KeyCode::Delete => Request::DeleteNextChar,
            KeyCode::Left if ctrl => Request::GoToPrevWord,
            KeyCode::Right if ctrl => Request::GoToNextWord,
            KeyCode::Left if !alt => Request::GoToPrevChar,
            KeyCode::Right if !alt => Request::GoToNextChar,
            KeyCode::Home => Request::GoToStart,
            KeyCode::End => Request::GoToEnd,
            _ => return None,
        })
    }

    /// Handle a key event; returns Some(edit?) if the key mapped to a request.
    pub fn handle_key(&mut self, key: &KeyEvent) -> Option<bool> {
        let req = Self::to_request(key)?;
        Some(self.execute(req))
    }
}
