/// root + display_path (lexical).
pub fn fs_path(display_path: &str, root: &str) -> String {
    if display_path.starts_with('/') {
        return display_path.to_string();
    }
    if root == "." || root.is_empty() {
        return display_path.to_string();
    }
    if root.ends_with('/') {
        format!("{root}{display_path}")
    } else {
