// Configuration loading: reads <config_dir>/config.json5 (a small
// JSON5 subset), merges user keybindings over the defaults.

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use std::collections::HashMap;
use std::path::PathBuf;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Action {
    Quit,
    Suspend,
    Resume,
    Refresh,
    LoopOverTabs,
    BackLoopOverTabs,
    ProcessReplace,
    ShowHelp,
    Help,
    Tick,
    Render,
}

impl Action {
    pub fn from_name(name: &str) -> Option<Action> {
        Some(match name {
            "Quit" => Action::Quit,
            "Suspend" => Action::Suspend,
            "Resume" => Action::Resume,
            "Refresh" => Action::Refresh,
            "LoopOverTabs" => Action::LoopOverTabs,
            "BackLoopOverTabs" => Action::BackLoopOverTabs,
            "ProcessReplace" => Action::ProcessReplace,
            "ShowHelp" => Action::ShowHelp,
            "Help" => Action::Help,
            "Tick" => Action::Tick,
            "Render" => Action::Render,
            _ => return None,
        })
    }
}

#[derive(Clone, Default)]
pub struct Config {
    pub keybindings: HashMap<KeyEvent, Action>,
}

fn default_keybindings() -> Vec<(KeyEvent, Action)> {
    let ctrl = KeyModifiers::CONTROL;
    vec![
        (KeyEvent::new(KeyCode::Char('d'), ctrl), Action::Quit),
        (KeyEvent::new(KeyCode::Char('c'), ctrl), Action::Quit),
        (KeyEvent::new(KeyCode::Char('z'), ctrl), Action::Suspend),
        (KeyEvent::new(KeyCode::Char('r'), ctrl), Action::Refresh),
        (KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE), Action::LoopOverTabs),
        (KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT), Action::BackLoopOverTabs),
        (KeyEvent::new(KeyCode::Char('o'), ctrl), Action::ProcessReplace),
        (KeyEvent::new(KeyCode::Char('b'), ctrl), Action::ShowHelp),
    ]
}

impl Config {
    pub fn load() -> Result<Config, String> {
        let mut map: HashMap<KeyEvent, Action> = default_keybindings().into_iter().collect();
        let path = config_path();
        if let Ok(content) = std::fs::read_to_string(&path) {
            let rel = crate::relative_display_path(&path);
            let value = crate::json5::parse(&content).map_err(|e| format!("{e} in {rel}"))?;
            let obj = match &value {
                crate::json5::Value::Object(o) => o.clone(),
                other => {
                    return Err(format!(
                        "invalid type: {}, expected a map in {rel} in {rel}",
                        type_desc(other)
                    ));
                }
            };
            for (k, v) in &obj {
                if k == "keybindings" {
                    let bindings = match v {
                        crate::json5::Value::Object(o) => o,
                        other => {
                            return Err(format!(
                                "invalid type: {}, expected a map",
                                type_desc(other)
                            ));
                        }
                    };
                    for (key_str, action_val) in bindings {
                        let action = parse_action_value(action_val, key_str, &rel)?;
                        let key_event = parse_key_event(key_str).unwrap();
                        map.insert(key_event, action);
                    }
                }
            }
        }
        Ok(Config { keybindings: map })
    }
}

fn parse_action_value(v: &crate::json5::Value, key_str: &str, rel: &str) -> Result<Action, String> {
    use crate::json5::Value;
    match v {
        Value::String(s) => Action::from_name(s)
            .ok_or_else(|| format!("Unknown Action variant: {s}")),
        Value::Bool(b) => Err(format!("Unknown Action variant: {b}")),
        Value::Number(raw, _) => Err(format!("Unknown Action variant: {raw}")),
        Value::Null => Err(format!(
            "invalid type: unit value, expected a string for key `keybindings.{}` in {rel}",
            key_str.to_lowercase()
        )),
        Value::Array(_) => Err(format!(
            "invalid type: sequence, expected a string for key `keybindings.{}` in {rel}",
            key_str.to_lowercase()
        )),
        Value::Object(_) => Err(format!(
            "invalid type: map, expected a string for key `keybindings.{}`",
            key_str.to_lowercase()
        )),
    }
}

fn type_desc(v: &crate::json5::Value) -> String {
    use crate::json5::Value;
    match v {
        Value::Null => "unit value".to_string(),
        Value::Bool(b) => format!("boolean `{b}`"),
        Value::Number(raw, is_float) => {
            if *is_float {
                format!("floating point `{}`", fmt_float(raw))
            } else if raw.parse::<i64>().is_ok() {
                format!("64-bit integer `{raw}`")
            } else {
                format!("integer `{raw}`")
            }
        }
        Value::String(s) => format!("string \"{s}\""),
        Value::Array(_) => "sequence".to_string(),
        Value::Object(_) => "map".to_string(),
    }
}

fn fmt_float(raw: &str) -> String {
    // serde prints floats via ryu (e.g. 1.5 -> "1.5")
    if let Ok(f) = raw.parse::<f64>() {
        let s = format!("{f}");
        s
    } else {
        raw.to_string()
    }
}

pub fn config_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        if !x.is_empty() && x.starts_with('/') {
            return PathBuf::from(x).join("serpl");
        }
    }
    let home = home_dir();
    home.join(".config").join("serpl")
}

pub fn home_dir() -> PathBuf {
    if let Ok(h) = std::env::var("HOME") {
        if !h.is_empty() {
            return PathBuf::from(h);
        }
    }
    // fallback to passwd entry
    unsafe {
        let uid = libc_getuid();
        let pw = libc_getpwuid(uid);
        if !pw.is_null() {
            let dir = (*pw).pw_dir;
            if !dir.is_null() {
                let cstr = std::ffi::CStr::from_ptr(dir);
                return PathBuf::from(cstr.to_string_lossy().to_string());
            }
        }
    }
    PathBuf::new()
}

// Minimal libc bindings (avoid extra crates).
#[repr(C)]
struct Passwd {
    pw_name: *const std::os::raw::c_char,
    pw_passwd: *const std::os::raw::c_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *const std::os::raw::c_char,
    pw_dir: *const std::os::raw::c_char,
    pw_shell: *const std::os::raw::c_char,
}
extern "C" {
    fn getuid() -> u32;
    fn getpwuid(uid: u32) -> *const Passwd;
}
unsafe fn libc_getuid() -> u32 {
    getuid()
}
unsafe fn libc_getpwuid(uid: u32) -> *const Passwd {
    getpwuid(uid)
}

pub fn config_path() -> PathBuf {
    config_dir().join("config.json5")
}

/// Parse a keybinding string like "<Ctrl-x>", "Ctrl-x", "x", "<F5>", "<Tab>".
/// Returns Err with the lowercased, stripped remainder (the caller unwraps,
/// producing the reference panic message).
pub fn parse_key_event(raw: &str) -> Result<KeyEvent, String> {
    let stripped = raw
        .trim()
        .trim_start_matches('<')
        .trim_end_matches('>')
        .to_lowercase();
    if stripped.is_empty() {
        return Err(stripped);
    }
    let parts: Vec<&str> = split_key_parts(&stripped);
    let (key_part, mod_parts) = parts.split_last().unwrap();
    let mut modifiers = KeyModifiers::NONE;
    for m in mod_parts {
        match *m {
            "ctrl" => modifiers |= KeyModifiers::CONTROL,
            "alt" => modifiers |= KeyModifiers::ALT,
            "shift" => modifiers |= KeyModifiers::SHIFT,
            _ => return Err(stripped.clone()),
        }
    }
    let code = parse_key_code(key_part).ok_or_else(|| stripped.clone())?;
    // crossterm reports BackTab with SHIFT; "<Shift-Tab>" also maps to BackTab.
    let (code, modifiers) = match code {
        KeyCode::BackTab => (code, modifiers | KeyModifiers::SHIFT),
        KeyCode::Tab if modifiers.contains(KeyModifiers::SHIFT) => (KeyCode::BackTab, modifiers),
        _ => (code, modifiers),
    };
    Ok(KeyEvent::new(code, modifiers))
}

fn split_key_parts(s: &str) -> Vec<&str> {
    // Split on '-' but keep a trailing '-' key (e.g. "ctrl--" -> ["ctrl", "-"])
    let mut parts: Vec<&str> = s.split('-').collect();
    if s.ends_with("--") && parts.len() >= 2 {
        // last two empty parts represent key "-"
        parts.truncate(parts.len() - 1);
        if let Some(last) = parts.last_mut() {
            *last = "-";
        }
    }
    parts
}

fn parse_key_code(s: &str) -> Option<KeyCode> {
    Some(match s {
        "esc" => KeyCode::Esc,
        "enter" => KeyCode::Enter,
        "tab" => KeyCode::Tab,
        "backtab" => KeyCode::BackTab,
        "backspace" => KeyCode::Backspace,
        "delete" => KeyCode::Delete,
        "insert" => KeyCode::Insert,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "pageup" => KeyCode::PageUp,
        "pagedown" => KeyCode::PageDown,
