{"command":"cat > src/json5.rs <<'EOF'
// A small JSON5 parser sufficient for the config file format, with
// pest-style span errors for syntax failures.

#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Bool(bool),
    /// (raw text, is_float)
    Number(String, bool),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

pub fn parse(src: &str) -> Result<Value, String> {
    let mut p = Parser {
        src,
        chars: src.char_indices().collect(),
        pos: 0,
    };
    p.skip_ws();
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos < p.chars.len() {
        return Err(p.error_at(p.byte_pos(), EXPECTED_VALUE));
    }
    Ok(v)
}

const EXPECTED_VALUE: &str = "array, boolean, null, number, object, or string";

struct Parser<'a> {
    src: &'a str,
    chars: Vec<(usize, char)>,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn byte_pos(&self) -> usize {
        self.chars.get(self.pos).map(|(i, _)| *i).unwrap_or(self.src.len())
    }
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).map(|(_, c)| *c)
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn error_at(&self, byte_pos: usize, expected: &str) -> String {
        let prefix = &self.src[..byte_pos.min(self.src.len())];
        let line_no = prefix.matches('\n').count() + 1;
        let line_start = prefix.rfind('\n').map(|i| i + 1).unwrap_or(0);
        let col = prefix[line_start..].chars().count() + 1;
        let line_end = self.src[line_start..]
            .find('\n')
            .map(|i| line_start + i)
            .unwrap_or(self.src.len());
        let line_text = &self.src[line_start..line_end];
        let indent = " ".repeat(line_no.to_string().len());
        format!(
            "\n --> {line_no}:{col}\n{indent} |\n{line_no} | {line_text}\n{indent} | {}^---\n{indent} |\n{indent} = expected {expected}",
            " ".repeat(col - 1)
        )
    }
    fn err_here(&self, expected: &str) -> String {
        self.error_at(self.byte_pos(), expected)
    }

    fn skip_ws(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('/') => {
                    let next = self.chars.get(self.pos + 1).map(|(_, c)| *c);
                    match next {
                        Some('/') => {
                            while let Some(c) = self.peek() {
                                if c == '\n' {
                                    break;
                                }
                                self.pos += 1;
                            }
                        }
                        Some('*') => {
                            self.pos += 2;
                            while self.pos < self.chars.len() {
                                if self.peek() == Some('*')
                                    && self.chars.get(self.pos + 1).map(|(_, c)| *c) == Some('/')
                                {
                                    self.pos += 2;
                                    break;
                                }
                                self.pos += 1;
                            }
                        }
                        _ => return,
                    }
                }
                _ => return,
            }
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') | Some('\'') => Ok(Value::String(self.parse_string()?)),
            Some(c) if c.is_ascii_alphabetic() => {
                let start_byte = self.byte_pos();
                let ident = self.parse_ident();
                match ident.as_str() {
                    "true" => Ok(Value::Bool(true)),
                    "false" => Ok(Value::Bool(false)),
                    "null" => Ok(Value::Null),
                    "Infinity" | "+Infinity" => Ok(Value::Number("inf".into(), true)),
                    "NaN" => Ok(Value::Number("NaN".into(), true)),
                    _ => Err(self.error_at(start_byte, EXPECTED_VALUE)),
                }
            }
            Some(c) if c.is_ascii_digit() || c == '+' || c == '-' || c == '.' => self.parse_number(),
            _ => Err(self.err_here(EXPECTED_VALUE)),
        }
    }

    fn parse_ident(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '$' {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        s
    }

    fn parse_number(&mut self) -> Result<Value, String> {
        let start = self.pos;
        let start_byte = self.byte_pos();
        if matches!(self.peek(), Some('+') | Some('-')) {
            self.pos += 1;
        }
        // hex?
        if self.peek() == Some('0')
            && matches!(self.chars.get(self.pos + 1).map(|(_, c)| *c), Some('x') | Some('X'))
        {
            self.pos += 2;
            let hs = self.pos;
            while self.peek().map(|c| c.is_ascii_hexdigit()).unwrap_or(false) {
                self.pos += 1;
            }
            if self.pos == hs {
                return Err(self.error_at(start_byte, EXPECTED_VALUE));
            }
            let hex: String = self.chars[hs..self.pos].iter().map(|(_, c)| *c).collect();
            let v = i64::from_str_radix(&hex, 16).unwrap_or(0);
            let sign = if self.chars[start].1 == '-' { "-" } else { "" };
            return Ok(Value::Number(format!("{sign}{v}"), false));
        }
        let mut is_float = false;
        let mut saw_digit = false;
        while let Some(c) = self.peek() {
            match c {
                '0'..='9' => {
                    saw_digit = true;
                    self.pos += 1;
                }
                '.' => {
                    is_float = true;
                    self.pos += 1;
                }
                'e' | 'E' => {
                    is_float = true;
                    self.pos += 1;
                    if matches!(self.peek(), Some('+') | Some('-')) {
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
        if !saw_digit {
            return Err(self.error_at(start_byte, EXPECTED_VALUE));
        }
        let raw: String = self.chars[start..self.pos].iter().map(|(_, c)| *c).collect();
        Ok(Value::Number(raw, is_float))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        let quote = self.bump().unwrap();
        let mut s = String::new();
        loop {
            match self.bump() {
                None => return Err(self.err_here(EXPECTED_VALUE)),
                Some(c) if c == quote => break,
                Some('\\') => match self.bump() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('0') => s.push('\0'),
                    Some('\n') => {}
                    Some('u') => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            match self.bump().and_then(|c| c.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => break,
                            }
                        }
                        if let Some(ch) = char::from_u32(code) {
                            s.push(ch);
                        }
                    }
                    Some(other) => s.push(other),
                    None => return Err(self.err_here(EXPECTED_VALUE)),
                },
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_key(&mut self) -> Result<String, String> {
        self.skip_ws();
        match self.peek() {
            Some('"') | Some('\'') => self.parse_string(),
            Some(c) if c.is_ascii_alphabetic() || c == '_' || c == '$' => Ok(self.parse_ident()),
            _ => Err(self.err_here(EXPECTED_VALUE)),
        }
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.bump(); // {
        let mut obj = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some('}') {
                self.pos += 1;
                break;
            }
            let key = self.parse_key()?;
            self.skip_ws();
            if self.bump() != Some(':') {
                return Err(self.err_here(EXPECTED_VALUE));
            }
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some('}') => {
                    self.pos += 1;
                    break;
                }
                _ => return Err(self.err_here(EXPECTED_VALUE)),
            }
        }
        Ok(Value::Object(obj))
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.bump(); // [
        let mut arr = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(']') {
                self.pos += 1;
                break;
            }
            let val = self.parse_value()?;
            arr.push(val);
            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.pos += 1;
                }
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                _ => return Err(self.err_here(EXPECTED_VALUE)),
            }
        }
        Ok(Value::Array(arr))
    }
}
