use std::io::Write;

pub enum Report {
    /// `Error: <msg>\n\nLocation:\n    <location>`
    WithLocation(String, &'static str),
    /// `Error: \n   0: <red msg>`
    Simple(String),
}

pub fn print_report(r: &Report) {
    let stderr = std::io::stderr();
    let mut w = stderr.lock();
    let _ = writeln!(w, "serpl error: Something went wrong");
    match r {
        Report::WithLocation(msg, loc) => {
            let _ = writeln!(w, "Error: {msg}");
            let _ = writeln!(w);
            let _ = writeln!(w, "Location:");
            let _ = writeln!(w, "    {loc}");
        }
        Report::Simple(msg) => {
            let _ = writeln!(w, "Error: ");
            let _ = writeln!(w, "   0: \x1b[91m{msg}\x1b[0m");
        }
    }
}

pub fn io_error_string(e: &std::io::Error) -> String {
    // std::io::Error Display already gives "Resource temporarily unavailable (os error 11)" etc.
    format!("{e}")
}

/// Install the panic hook that mimics color-eyre's panic output and report
/// file generation.
pub fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let _ = crate::terminal::restore_terminal();
        let location = info
            .location()
            .map(|l| (l.file().to_string(), l.line()))
            .unwrap_or_default();
        let message = if let Some(s) = info.payload().downcast_ref::<&str>() {
            (*s).to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let report_path = write_report(&location, &message);
        let stderr = std::io::stderr();
        let mut w = stderr.lock();
        let _ = writeln!(w, "Well, this is embarrassing.");
        let _ = writeln!(w);
        let _ = writeln!(w, "serpl had a problem and crashed. To help us diagnose the problem you can send us a crash report.");
        let _ = writeln!(w);
        let _ = writeln!(w, "We have generated a report file at \"{}\". Submit an issue or email with the subject of \"serpl Crash Report\" and include the report as an attachment.", report_path);
        let _ = writeln!(w);
        let _ = writeln!(w, "- Authors: Yassine Bridi <ybridi@gmail.com>");
        let _ = writeln!(w);
        let _ = writeln!(w, "We take privacy seriously, and do not perform any automated error collection. In order to improve the software, we rely on people to submit reports.");
        let _ = writeln!(w);
        let _ = writeln!(w, "Thank you kindly!");
        let _ = writeln!(w, "\x1b[31mThe application panicked (crashed).\x1b[0m");
        let _ = writeln!(w, "Message:  \x1b[36m{message}\x1b[0m");
        let _ = writeln!(w, "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m", location.0, location.1);
        let _ = writeln!(w);
        let _ = writeln!(w, "This is a bug. Consider reporting it at https://github.com/yassinebridi/serpl");
    }));
}

fn write_report(location: &(String, u32), message: &str) -> String {
    let uuid = make_uuid();
    let path = std::env::temp_dir().join(format!("report-{uuid}.toml"));
    let bt = std::backtrace::Backtrace::force_capture();
    let bt_str = format!("{bt}");
    // check for single quotes in message
    let cause = toml_escape(message);
    let content = format!(
        "name = \"serpl\"\noperating_system = \"{}\"\ncrate_version = \"0.3.4\"\nexplanation = \"\"\"\nPanic occurred in file '{}' at line {}\n\"\"\"\ncause = '{}'\nmethod = \"Panic\"\nbacktrace = \"\"\"\n{}",
        os_display(),
        location.0,
        location.1,
        cause,
        // keep our format brief; original has frames. Provide backtrace in a similar envelope.
        format!("\n{bt_str}\"\"\"")
    );
    let _ = std::fs::write(&path, content);
    path.to_string_lossy().to_string()
}

fn toml_escape(s: &str) -> String {
    // human-panic serialises via TOML; if the message contains single quotes
    // it switches quoting style - use basic escaping into single-quoted when
    // possible, otherwise fall back to escaped double-quoted content.
    // We keep it simple and replace single quotes rarely matches.
    s.replace('\\', "\\\\")
}

fn os_display() -> String {
    // Read /etc/os-release for a distro string similar to os_info's format:
    // e.g. "Ubuntu 22.4.0 [64-bit]".
    if let Ok(content) = std::fs::read_to_string("/etc/os-release") {
        let mut name = "";
        let mut version_id = "";
        for line in content.lines() {
            if let Some(v) = line.strip_prefix("NAME=") {
                name = v.trim_matches('"');
            }
            if let Some(v) = line.strip_prefix("VERSION_ID=") {
                version_id = v.trim_matches('"');
            }
        }
        if !name.is_empty() {
            // os_info appends .0 for many distros; approximate.
            let ver = if version_id.is_empty() {
                String::new()
            } else if version_id.matches('.').count() >= 2 {
                version_id.to_string()
            } else {
                format!("{version_id}.0")
            };
            return format!("{name} {ver} [64-bit]");
        }
    }
    "Linux [64-bit]".to_string()
}

fn make_uuid() -> String {
    let mut bytes = [0u8; 16];
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0) as u64
        ^ (std::process::id() as u64).wrapping_mul(0x9E3779B97F4A7C15);
    let mut state = seed;
    for b in bytes.iter_mut() {
        // xorshift
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        *b = state as u8;
    }
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7], bytes[8],
        bytes[9], bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]
    )
}
