fn write_report(location: &(String, u32), message: &str) -> String {
    let uuid = make_uuid();
    let path = std::env::temp_dir().join(format!("report-{uuid}.toml"));
    let bt = std::backtrace::Backtrace::force_capture();
    let bt_str = format!("{bt}");
    // check for single quotes in message
    let cause = toml_escape(message);
    let content = format!(
        "name = \"serpl\"\noperating_system = \"{}\"\ncrate_version = \"0.3.4\"\nexplanation = \"\"\"\nPanic occurred in file '{}' at line {}\n\"\"\"\ncause = '{}'\nmethod = \"Panic\"\nbacktrace = \"\"\"\n{}",
        os_display(),
        location.0,
        location.1,
        cause,
        // keep our format brief; original has frames. Provide backtrace in a similar envelope.
        format!("\n{bt_str}\"\"\"")
    );
    let _ = std::fs::write(&path, content);
    path.to_string_lossy().to_string()
}

fn toml_escape(s: &str) -> String {
    // human-panic serialises via TOML; if the message contains single quotes
    // it switches quoting style - use basic escaping into single-quoted when
    // possible, otherwise fall back to escaped double-quoted content.
    // We keep it simple and replace single quotes rarely matches.
    s.replace('\\', "\\\\")
}

fn os_display() -> String {
    // Read /etc/os-release for a distro string similar to os_info's format:
    // e.g. "Ubuntu 22.4.0 [64-bit]".
    if let Ok(content) = std::fs::read_to_string("/etc/os-release") {
        let mut name = "";
        let mut version_id = "";
        for line in content.lines() {
            if let Some(v) = line.strip_prefix("NAME=") {
                name = v.trim_matches('"');
            }
            if let Some(v) = line.strip_prefix("VERSION_ID=") {
                version_id = v.trim_matches('"');
            }
        }
        if !name.is_empty() {
            // os_info appends .0 for many distros; approximate.
            let ver = if version_id.is_empty() {
                String::new()
            } else if version_id.matches('.').count() >= 2 {
                version_id.to_string()
            } else {
                format!("{version_id}.0")
            };
            return format!("{name} {ver} [64-bit]");
        }
    }
    "Linux [64-bit]".to_string()
}

fn make_uuid() -> String {
    let mut bytes = [0u8; 16];
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0) as u64
        ^ (std::process::id() as u64).wrapping_mul(0x9E3779B97F4A7C15);
    let mut state = seed;
    for b in bytes.iter_mut() {
        // xorshift
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        *b = state as u8;
    }
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7], bytes[8],
        bytes[9], bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]
    )
}
EOF
