use crate::modes::{ReplaceMode, SearchMode};

pub fn process_line_replace(
    path: &str,
    line_number: usize,
    search_text: &str,
    replace_text: &str,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
) {
    let content = std::fs::read_to_string(path).expect("Unable to read file");
    let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
    if line_number == 0 {
        crate::redux::utils::write_file(path, &lines.join("\n"));
        return;
    }
    let idx = line_number - 1;
    match replace_mode {
        ReplaceMode::DeleteLine => {
            if idx < lines.len() {
                lines.remove(idx);
            }
        }
        _ => {
            if let Some(line) = lines.get_mut(idx) {
                *line = crate::modes::do_replace(
                    line,
                    search_text,
                    replace_text,
                    search_mode,
                    replace_mode,
                );
            }
        }
    }
    crate::redux::utils::write_file(path, &lines.join("\n"));
}
