impl PreviewData {
    pub fn empty() -> Self {
        Self { rows: Vec::new(), groups: Vec::new() }
    }
}

pub struct App {
    pub should_quit: bool,
    pub should_suspend: bool,
    pub config: Config,
    pub project_root: String,

    pub focus: Focus,
    /// focus before the confirm dialog was opened (used for pane cycling
    /// while stuck in the confirm state)
    pub prev_focus: Focus,

    pub search_input: Input,
    pub replace_input: Input,
    pub search_mode: SearchMode,
    pub replace_mode: ReplaceMode,

    pub results: SearchResults,
    pub result_state: ListState,

    pub preview: PreviewData,
    pub preview_file: Option<String>,
    pub preview_state: ListState,

    pub show_help: bool,
    pub help_tab: usize,

    pub confirm_visible: bool,
    pub confirm_selected: usize, // 0 = Continue, 1 = Cancel

    pub notifications: Vec<Notification>,
    pub needs_search: bool,
}

impl App {
    pub fn new(config: Config, project_root: String) -> Self {
        Self {
            should_quit: false,
            should_suspend: false,
            config,
            project_root,
            focus: Focus::Search,
            prev_focus: Focus::Search,
            search_input: Input::default(),
            replace_input: Input::default(),
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            results: SearchResults::default(),
            result_state: ListState::default(),
            preview: PreviewData::empty(),
            preview_file: None,
            preview_state: ListState::default(),
            show_help: false,
            help_tab: 0,
            confirm_visible: false,
            confirm_selected: 1,
            notifications: Vec::new(),
            needs_search: false,
        }
    }

    pub fn reset_after_all_replace(&mut self) {
        self.search_input.reset();
        self.replace_input.reset();
        self.search_mode = SearchMode::Simple;
        self.replace_mode = ReplaceMode::Simple;
        self.results = SearchResults::default();
        self.result_state = ListState::default();
        self.preview = PreviewData::empty();
        self.preview_file = None;
        self.preview_state = ListState::default();
        self.focus = Focus::Search;
        self.confirm_visible = false;
    }

    pub fn selected_file(&self) -> Option<&FileResult> {
        self.result_state.selected().and_then(|i| self.results.files.get(i))
    }

    pub fn do_search(&mut self) {
        self.needs_search = false;
        let q = self.search_input.value().to_string();
        if q.is_empty() {
            return;
        }
        self.results = crate::search::run_search(&q, self.search_mode, &self.project_root);
        // Selection in the result list is preserved (ListState), the preview
        // is not rebuilt on search (matches the reference behaviour).
    }

    pub fn rebuild_preview(&mut self, for_path: &str) {
        self.preview = build_preview(&self.results, for_path);
        self.preview_file = Some(for_path.to_string());
    }

    pub fn notify_success(&mut self, msg: &str) {
        self.notifications.push(Notification::success(msg));
    }
    pub fn notify_error(&mut self, msg: &str) {
        self.notifications.push(Notification::error(msg));
    }
    pub fn prune_notifications(&mut self) {
        self.notifications.retain(|n| !n.expired());
    }

    pub fn action_for_key(&self, key: &crossterm::event::KeyEvent) -> Option<Action> {
        // crossterm reports Tab with SHIFT as BackTab; also Ctrl+letter
        // combinations arrive with lower-case char. Normalise lookup by also
        // trying a canonicalised event.
        if let Some(a) = self.config.keybindings.get(key) {
            return Some(*a);
        }
        let mut k = *key;
        if k.code == crossterm::event::KeyCode::BackTab {
            k.modifiers = crossterm::event::KeyModifiers::SHIFT;
            if let Some(a) = self.config.keybindings.get(&k) {
                return Some(*a);
            }
            k.modifiers = crossterm::event::KeyModifiers::NONE;
            if let Some(a) = self.config.keybindings.get(&k) {
                return Some(*a);
            }
        }
        if let crossterm::event::KeyCode::Char(c) = k.code {
            if c.is_uppercase() {
                // bindings are stored with the literal (possibly upper-case)
                // char; crossterm gives e.g. 'J'. Nothing to do.
            }
        }
        None
    }

    pub fn loop_focus(&mut self, base: Focus, forward: bool) {
        let order = [Focus::Search, Focus::Replace, Focus::ResultList];
        let cur = match base {
            Focus::Search => 0,
            Focus::Replace => 1,
            Focus::ResultList | Focus::Preview => 2,
            Focus::ConfirmDialog => 0,
        };
        let next = if forward {
            (cur + 1) % 3
        } else {
            (cur + 2) % 3
        };
        self.focus = order[next];
    }
}

fn find_match_entry(lines: &[LineEntry], path: &str, line_number: usize) -> Option<usize> {
    lines
        .iter()
        .position(|e| e.is_match && e.path == path && e.line_number == Some(line_number))
}

/// Build preview rows/groups for a file from the current results.
pub fn build_preview(results: &SearchResults, path: &str) -> PreviewData {
    let Some(file) = results.files.iter().find(|f| f.path == path) else {
        return PreviewData::empty();
    };
    let mut rows: Vec<PreviewRow> = Vec::new();
    let mut groups: Vec<PreviewGroup> = Vec::new();

    for &ln in &file.match_lines {
        let Some(mid) = find_match_entry(&results.lines, path, ln) else {
            continue;
        };
        let group_idx = groups.len();
        let start_row = rows.len();

        // before-context: walk backwards collecting up to 3 entries,
        // stopping after (and including) the first match entry found.
        let mut before: Vec<usize> = Vec::new();
        let mut i = mid;
        while i > 0 && before.len() < 3 {
            i -= 1;
            before.push(i);
            if results.lines[i].is_match {
                break;
            }
        }
        before.reverse();
        let n_before = before.len();
        for (k, &ei) in before.iter().enumerate() {
            let dist = n_before - k;
            let computed = ln.saturating_sub(dist);
            rows.push(PreviewRow {
                kind: RowKind::Line { entry: ei, computed_ln: computed, is_match: false },
                group: group_idx,
            });
        }
        let match_row = rows.len();
        rows.push(PreviewRow {
            kind: RowKind::Line { entry: mid, computed_ln: ln, is_match: true },
            group: group_idx,
        });
        // after-context: following entries with the same path, up to 3,
        // stopping before the next match entry.
        let mut j = mid + 1;
        let mut dist = 0usize;
        while j < results.lines.len() && dist < 3 {
            let e = &results.lines[j];
            if e.is_match || e.path != path {
                break;
            }
            dist += 1;
            rows.push(PreviewRow {
                kind: RowKind::Line { entry: j, computed_ln: ln + dist, is_match: false },
                group: group_idx,
            });
            j += 1;
        }
        let end_row = rows.len();
        rows.push(PreviewRow { kind: RowKind::Separator, group: group_idx });
        groups.push(PreviewGroup {
            file_path: path.to_string(),
            line_number: ln,
            start_row,
            match_row,
            end_row,
        });
    }
    PreviewData { rows, groups }
}
