        .direction(Direction::Vertical)
        .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)])
        .split(horizontal[0]);
    let preview_area = horizontal[1];

    // Search input
    draw_input(
        f,
        left[0],
        app,
        true,
        app.focus == Focus::Search,
    );
    // Replace input
    draw_input(
        f,
        left[1],
        app,
        false,
        app.focus == Focus::Replace,
    );
    draw_result_list(f, left[2], app);
    draw_preview(f, preview_area, app);
    draw_footer(f, vertical[1], app);

    let content_area = vertical[0];
    if app.show_help {
        draw_help(f, app, content_area);
    } else if app.confirm_visible {
        draw_confirm(f, app, content_area);
    }
    draw_notifications(f, app, content_area);
}

fn draw_input(f: &mut Frame, area: Rect, app: &App, is_search: bool, active: bool) {
    let (input, title, mode_label) = if is_search {
        (&app.search_input, "Search", app.search_mode.label())
    } else {
        (&app.replace_input, "Replace", app.replace_mode.label())
    };
    let delete_line = !is_search && app.replace_mode == ReplaceMode::DeleteLine;
    let border_style = if delete_line && !active {
        Style::default().fg(Color::DarkGray)
    } else if active {
        active_style()
    } else {
        inactive_style()
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(border_style)
        .title(title)
        .title(Line::raw(format!("[{mode_label}]")).right_aligned());
    let inner = block.inner(area);
    let text_style = if delete_line {
        Style::default().fg(Color::DarkGray)
    } else {
        Style::default().fg(Color::White)
    };
    let display_value: String = if delete_line {
        "[Entire line will be deleted]".to_string()
    } else {
        input.value().to_string()
    };
    let scroll = input.visual_scroll(inner.width as usize);
    let scroll_u16 = scroll.min(u16::MAX as usize) as u16;
    let para = Paragraph::new(Line::styled(display_value.clone(), text_style))
        .style(text_style)
        .scroll((0, scroll_u16));
    f.render_widget(block, area);
    if inner.width > 0 && inner.height > 0 {
        f.render_widget(para, inner);
    }
    if active && inner.width > 0 {
        if delete_line {
            // cursor at inner.x + 33 capped - reference parks it at the
            // second-to-last column of the block (x=34 for a 36-wide pane)
            let x = area.x + area.width.saturating_sub(2);
            f.set_cursor_position((x, inner.y));
        } else {
            let cx = inner.x as usize + input.visual_cursor() - scroll;
            let cx = cx.min((inner.x + inner.width.saturating_sub(1)) as usize);
            f.set_cursor_position((cx as u16, inner.y));
        }
    }
}

fn draw_result_list(f: &mut Frame, area: Rect, app: &mut App) {
    let active = app.focus == Focus::ResultList;
    let border_style = if active { active_style() } else { inactive_style() };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(border_style)
        .title("Result List");
    let items: Vec<ListItem> = app
        .results
        .files
        .iter()
        .map(|file| {
            ListItem::new(Line::from(vec![
                Span::styled(format!("{} (", file.path), Style::default().fg(Color::White)),
                Span::styled(format!("{}", file.count), Style::default().fg(Color::Yellow)),
                Span::styled(")".to_string(), Style::default().fg(Color::White)),
            ]))
        })
        .collect();
    let list = List::new(items)
        .block(block)
        .highlight_style(Style::default().bg(Color::Blue));
    let mut state = std::mem::take(&mut app.result_state);
    f.render_stateful_widget(list, area, &mut state);
    app.result_state = state;
}

fn trim_line_end(text: &str) -> &str {
    let t = text.strip_suffix('\n').unwrap_or(text);
    t
}

fn draw_preview(f: &mut Frame, area: Rect, app: &mut App) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(preview_border_style(app))
        .title("Preview");

    let replace_text = app.replace_input.value().to_string();
    let replace_mode = app.replace_mode;
    let in_preview_focus = app.focus == Focus::Preview;

    let mut items: Vec<ListItem> = Vec::new();
    for row in &app.preview.rows {
        match &row.kind {
            RowKind::Separator => {
                let style = if in_preview_focus {
                    Style::default().fg(Color::Yellow)
                } else {
                    Style::default().fg(Color::DarkGray)
                };
                items.push(ListItem::new(Line::styled("-".repeat(400), style)));
            }
            RowKind::Line { entry, computed_ln, is_match } => {
                let Some(e) = app.results.lines.get(*entry) else {
                    continue;
                };
                let text = trim_line_end(&e.text).to_string();
                let line = if *is_match {
                    build_match_line(*computed_ln, &text, &e.submatches, &replace_text, replace_mode)
                } else {
                    Line::from(vec![
                        Span::styled(format!("{computed_ln:>4} "), Style::default().fg(Color::Blue)),
                        Span::styled(text, Style::default().fg(Color::DarkGray)),
                    ])
                };
                items.push(ListItem::new(line));
            }
        }
    }
    let list = List::new(items)
        .block(block)
        .highlight_style(
            Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
        )
        .highlight_symbol(">");
    let mut state = std::mem::take(&mut app.preview_state);
    f.render_stateful_widget(list, area, &mut state);
    app.preview_state = state;
}

fn build_match_line(
    ln: usize,
    text: &str,
    submatches: &[crate::search::SubMatch],
    replace_text: &str,
    replace_mode: ReplaceMode,
) -> Line<'static> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    spans.push(Span::styled(
        format!("{ln:>4} "),
        Style::default().fg(Color::LightGreen),
    ));
    if replace_mode == ReplaceMode::DeleteLine {
        spans.push(Span::styled(
            text.to_string(),
            Style::default()
                .fg(Color::White)
                .bg(Color::Red)
                .add_modifier(Modifier::CROSSED_OUT),
        ));
        return Line::from(spans);
    }
    // truncate \r for span computations? Keep text as-is; submatch ranges are
    // byte offsets in the full line (without the trailing \n already removed).
    let mut last = 0usize;
    for sm in submatches {
        let before = text.get(last..sm.start).unwrap_or("");
        if !before.is_empty() {
            spans.push(Span::raw(before.to_string()));
        }
        let matched = text.get(sm.start..sm.end).unwrap_or("");
        if replace_text.is_empty() {
            spans.push(Span::styled(matched.to_string(), Style::default().bg(Color::Blue)));
        } else {
            spans.push(Span::styled(
                matched.to_string(),
                Style::default()
                    .fg(Color::White)
                    .bg(Color::LightRed)
                    .add_modifier(Modifier::CROSSED_OUT),
            ));
            let repl = if replace_mode == ReplaceMode::PreserveCase {
                preserve_case(matched, replace_text)
            } else {
                replace_text.to_string()
            };
            spans.push(Span::styled(
                repl,
                Style::default().fg(Color::White).bg(Color::Green),
            ));
        }
        last = sm.end;
    }
    let tail = text.get(last..).unwrap_or("");
    if !tail.is_empty() {
        spans.push(Span::raw(tail.to_string()));
    }
    Line::from(spans)
}

fn draw_footer(f: &mut Frame, area: Rect, app: &App) {
    let text = if app.show_help {
        "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
    } else {
        match app.focus {
            Focus::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>",
            Focus::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>",
            Focus::ResultList => "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>",
            Focus::Preview => "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>",
            Focus::ConfirmDialog => "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>",
        }
    };
    let para = Paragraph::new(Line::styled(text.to_string(), Style::default().fg(Color::Blue)));
    f.render_widget(para, area);
}

pub fn centered_fixed(width: u16, height: u16, area: Rect) -> Rect {
    let w = width.min(area.width);
    let h = height.min(area.height);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let y = area.y + (area.height.saturating_sub(h)) / 2;
    Rect { x, y, width: w, height: h }
}

fn draw_help(f: &mut Frame, app: &App, area: Rect) {
    let dialog = centered_fixed(80, 15, area);
    let border = Style::default().fg(Color::Yellow);
    let active_tab_style = Style::default().fg(Color::Green);
    // Build title: left-aligned line with tab spans.
    let (t1, t2) = if app.help_tab == 0 {
        (active_tab_style, border)
    } else {
        (border, active_tab_style)
    };
    let title = Line::from(vec![
        Span::styled(" [1] Global ", t1),
        Span::styled("─", border),
        Span::styled(" [2] Navigation ", t2),
    ]);
    let close_hint = Line::styled("Press 'q' to close", border).right_aligned();
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(border)
        .title(title)
        .title(close_hint);
    let text: Vec<Line> = if app.help_tab == 0 {
        vec![
            Line::raw(""),
            Line::raw(" - Ctrl-c: Quit"),
            Line::raw(" - Ctrl-d: Quit"),
            Line::raw(" - Ctrl-b: Help dialog"),
            Line::raw(" - Ctrl-o: Process Replace For All Files"),
            Line::raw(" - Ctrl-n: Loop through search and replace modes"),
            Line::raw(" - Enter: Select/Deselect file"),
            Line::raw(" - d: delete file/delete line from the replace process"),
            Line::raw(" - r: Replace Selected File Or Line"),
        ]
    } else {
        vec![
            Line::raw(""),
            Line::raw(" - Tab: Loop through panes"),
            Line::raw(" - j/UpArrow: Move up"),
            Line::raw(" - k/DownArrow: Move down"),
            Line::raw(" - h/g/LeftArrow: Move to Top"),
            Line::raw(" - l/G/RightArrow: Move to Bottom"),
        ]
    };
    let para = Paragraph::new(text)
        .style(Style::default().fg(Color::White))
        .block(block);
    f.render_widget(Clear, dialog);
    f.render_widget(para, dialog);
}

pub fn confirm_message(replace_empty: bool) -> &'static str {
    if replace_empty {
        "Replace text is empty, and replacing with an empty string will remove the matched text."
    } else {
        "This action will modify the files in this directory."
    }
}

fn draw_confirm(f: &mut Frame, app: &App, area: Rect) {
    let msg1 = confirm_message(app.replace_input.value().is_empty());
    let msg2 = "Are you sure you want to continue?";
    let width = ((msg1.len().max(msg2.len())) + 4).min(i32::MAX as usize) as u16;
    let dialog = centered_fixed(width, 8, area);
    let border = Style::default().fg(Color::Yellow);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(border)
        .title(Line::styled("Confirm Dialog", Style::default()).centered());
    let inner = block.inner(dialog);
    f.render_widget(Clear, dialog);
    f.render_widget(block, dialog);
    if inner.height == 0 || inner.width == 0 {
        return;
    }
    // Layout inside dialog: rows mimic the reference:
    // blank, msg lines (wrapped, centered), blank, blank, buttons
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(2),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
        ])
        .split(inner);
    let msg_style = Style::default().fg(Color::White);
    let msg = Paragraph::new(format!("{msg1}\n{msg2}"))
        .style(msg_style)
        .alignment(Alignment::Center)
        .wrap(ratatui::widgets::Wrap { trim: false });
    f.render_widget(msg, chunks[1]);

    let (cont_style, cancel_style) = if app.confirm_selected == 0 {
        (
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
            Style::default().fg(Color::White),
        )
    } else {
        (
            Style::default().fg(Color::White),
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
        )
    };
    let buttons = Paragraph::new(Line::from(vec![
        Span::styled(" Continue ", cont_style),
        Span::styled(" Cancel ", cancel_style),
    ]))
    .alignment(Alignment::Center);
    if chunks.len() > 4 {
        f.render_widget(buttons, chunks[4]);
    }
}

fn draw_notifications(f: &mut Frame, app: &App, area: Rect) {
    // Bottom of the last notification sits one row above the area bottom.
    let mut bottom: i32 = (area.y + area.height).saturating_sub(2) as i32;
    for n in app.notifications.iter() {
        let width = (n.message.len() + 4) as u16;
        let x = (area.x + area.width).saturating_sub(width + 1);
        let y = bottom - 2;
        if y < 0 {
            break;
        }
        let rect = Rect { x, y: y as u16, width, height: 3 };
        let color = match n.kind {
            NotificationKind::Success => Color::Blue,
            NotificationKind::Error => Color::Red,
        };
        let style = Style::default().fg(color).add_modifier(Modifier::BOLD);
        let para = Paragraph::new(Line::styled(n.message.clone(), style)).block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(style)
                .title("Notification"),
        );
        f.render_widget(Clear, rect);
        f.render_widget(para, rect);
        bottom = y - 1;
    }
}
