use crate::app::{build_preview, App, Focus};
use crate::config::Action;
use crate::input::Input;
use crate::modes::ReplaceMode;
use crossterm::event::{KeyCode, KeyEvent, KeyEventKind, KeyModifiers};

pub fn handle_key(app: &mut App, key: KeyEvent) {
    if key.kind == KeyEventKind::Release {
        return;
    }
    // Help overlay captures everything except global quit/suspend.
    if app.show_help {
        handle_global_actions(app, &key, true);
        if app.should_quit || app.should_suspend {
            return;
        }
        handle_help_key(app, key);
        return;
    }
    // Config-mapped global actions first (with dialog-specific handling for
    // LoopOverTabs / ProcessReplace / ShowHelp).
    if let Some(action) = app.action_for_key(&key) {
        match action {
            Action::Quit => {
                app.should_quit = true;
                return;
            }
            Action::Suspend => {
                app.should_suspend = true;
                return;
            }
            Action::LoopOverTabs | Action::BackLoopOverTabs => {
                let forward = action == Action::LoopOverTabs;
                if app.confirm_visible {
                    app.confirm_selected ^= 1;
                    return;
                }
                if app.focus == Focus::Preview {
                    // Tab in Preview: reference leaves Preview to Search
                    app.loop_focus(Focus::ResultList, forward);
                    return;
                }
                if app.focus == Focus::ConfirmDialog {
                    // stuck state: cycle from the pre-dialog focus
                    app.loop_focus(app.prev_focus, forward);
                    return;
                }
                let base = app.focus;
                app.loop_focus(base, forward);
                return;
            }
            Action::ProcessReplace => {
                if app.confirm_visible {
                    return;
                }
                open_confirm(app);
                return;
            }
            Action::ShowHelp => {
                if app.confirm_visible {
                    app.confirm_visible = false; // becomes stuck focus
                }
                app.show_help = true;
                return;
            }
            Action::Refresh => {
                if app.focus == Focus::Search {
                    app.needs_search = true;
                }
                return;
            }
            Action::Resume | Action::Help | Action::Tick | Action::Render => {
                return;
            }
        }
    }

    if app.confirm_visible {
        handle_confirm_key(app, key);
        return;
    }
    if app.focus == Focus::ConfirmDialog {
        // stuck: non-global keys are ignored (Ctrl-n handled below would not
        // reach panes either)
        return;
    }

    // Ctrl-n: loop modes (hardcoded, not in config)
    if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('n') {
        match app.focus {
            Focus::Search => {
                app.search_mode = app.search_mode.next();
                app.needs_search = true;
            }
            Focus::Replace => {
                app.replace_mode = app.replace_mode.next();
            }
            _ => {}
        }
        return;
    }

    match app.focus {
        Focus::Search => handle_search_key(app, key),
        Focus::Replace => handle_replace_key(app, key),
        Focus::ResultList => handle_result_key(app, key),
        Focus::Preview => handle_preview_key(app, key),
        Focus::ConfirmDialog => {}
    }
}

fn handle_global_actions(app: &mut App, key: &KeyEvent, _in_help: bool) {
    if let Some(action) = app.action_for_key(key) {
        match action {
            Action::Quit => app.should_quit = true,
            Action::Suspend => app.should_suspend = true,
            _ => {}
        }
    }
}

fn handle_help_key(app: &mut App, key: KeyEvent) {
    // Tab inside help cycles help tabs (Backtab is a global action, but the
    // dialog-specific handling in handle_key only routes here after globals;
    // LoopOverTabs inside help is Tab: we intercept Tab explicitly here via
    // the action check below.)
    if let Some(Action::LoopOverTabs) = app.action_for_key(&key) {
        app.help_tab = (app.help_tab + 1) % 2;
        return;
    }
    match key.code {
        KeyCode::Esc => app.show_help = false,
        KeyCode::Char('q') if key.modifiers.is_empty() => app.show_help = false,
        KeyCode::Right => app.help_tab = (app.help_tab + 1) % 2,
        KeyCode::Left => app.help_tab = (app.help_tab + 1) % 2,
        KeyCode::Char('1') => app.help_tab = 0,
        KeyCode::Char('2') => app.help_tab = 1,
        _ => {}
    }
}

fn open_confirm(app: &mut App) {
    if app.search_input.value().is_empty() {
        app.notify_error("Search text cannot be empty");
        return;
    }
    app.prev_focus = if app.focus == Focus::ConfirmDialog {
        app.prev_focus
    } else if app.focus == Focus::Preview {
        Focus::ResultList
    } else {
        app.focus
    };
    app.focus = Focus::ConfirmDialog;
    app.confirm_visible = true;
}

fn handle_confirm_key(app: &mut App, key: KeyEvent) {
    // Ctrl-n closes the dialog (leaving the stuck confirm focus)
    if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('n') {
        app.confirm_visible = false;
        return;
    }
    match key.code {
        KeyCode::Esc => {
            app.confirm_visible = false;
        }
        KeyCode::Enter => {
            if app.confirm_selected == 0 {
                // Continue
                process_replace_all(app);
            } else {
                app.confirm_visible = false;
            }
        }
        KeyCode::Char('h' | 'l' | 'j' | 'k' | 'g' | 'G')
        | KeyCode::Left
        | KeyCode::Right
        | KeyCode::Up
        | KeyCode::Down => {
            app.confirm_selected ^= 1;
        }
        _ => {}
    }
}

fn handle_search_key(app: &mut App, key: KeyEvent) {
    if key.code == KeyCode::Enter {
        if !app.search_input.value().is_empty() {
            app.needs_search = true;
        }
        return;
    }
    if let Some(req) = Input::to_request(&key) {
        let edit = app.search_input.execute(req);
        if edit && !app.search_input.value().is_empty() {
            app.needs_search = true;
        }
    }
}

fn handle_replace_key(app: &mut App, key: KeyEvent) {
    if app.replace_mode == ReplaceMode::DeleteLine {
        return;
    }
    let _ = app.replace_input.handle_key(&key);
}

fn is_next_key(key: &KeyEvent) -> bool {
    matches!(key.code, KeyCode::Char('j')) || key.code == KeyCode::Down
}
fn is_prev_key(key: &KeyEvent) -> bool {
    matches!(key.code, KeyCode::Char('k')) || key.code == KeyCode::Up
}
fn is_top_key(key: &KeyEvent) -> bool {
    matches!(key.code, KeyCode::Char('h' | 'g')) || key.code == KeyCode::Left
}
fn is_bottom_key(key: &KeyEvent) -> bool {
    matches!(key.code, KeyCode::Char('l' | 'G')) || key.code == KeyCode::Right
}

fn handle_result_key(app: &mut App, key: KeyEvent) {
    let len = app.results.files.len();
    if is_next_key(&key) || is_prev_key(&key) || is_top_key(&key) || is_bottom_key(&key) {
        if len == 0 {
            return;
        }
        let cur = app.result_state.selected();
        let next = if is_next_key(&key) {
            match cur {
                None => 0,
                Some(i) => (i + 1) % len,
            }
        } else if is_prev_key(&key) {
            match cur {
                None => len - 1,
                Some(0) => len - 1,
                Some(i) => i - 1,
            }
        } else if is_top_key(&key) {
            0
        } else {
            len - 1
        };
        app.result_state.select(Some(next));
        let path = app.results.files[next].path.clone();
        app.rebuild_preview(&path);
        return;
    }
    match key.code {
        KeyCode::Enter => {
            if app.result_state.selected().is_some() {
                app.focus = Focus::Preview;
            }
        }
        KeyCode::Char('d') => {
            delete_selected_file(app);
        }
        KeyCode::Char('r') => {
            replace_selected_file(app);
        }
        _ => {}
    }
}

fn delete_selected_file(app: &mut App) {
    let Some(idx) = app.result_state.selected() else { return };
    if idx >= app.results.files.len() {
        return;
    }
    let removed = app.results.files.remove(idx);
    app.results.lines.retain(|e| e.path != removed.path);
    if app.results.files.is_empty() {
        app.preview = crate::app::PreviewData::empty();
        app.preview_file = None;
        app.preview_state.select(None);
        return;
    }
    let next = idx.min(app.results.files.len() - 1);
    app.result_state.select(Some(next));
    let path = app.results.files[next].path.clone();
    app.rebuild_preview(&path);
}

fn replace_selected_file(app: &mut App) {
    let Some(idx) = app.result_state.selected() else { return };
    let Some(file) = app.results.files.get(idx) else { return };
    let display = file.path.clone();
    let fs = crate::search::fs_path(&display, &app.project_root);
    let search = app.search_input.value().to_string();
    let replace = app.replace_input.value().to_string();
    crate::redux::thunk::process_single_file_replace::process_single_file_replace(
        &fs,
        &search,
        &replace,
        app.search_mode,
        app.replace_mode,
    );
    app.notify_success("File replacement completed successfully");
    // Remove the file from the results; the preview intentionally stays
    // stale (reference behaviour).
    app.results.files.remove(idx);
    app.results.lines.retain(|e| e.path != display);
}

fn preview_select_match_row(app: &mut App, forward: bool) {
    let rows = &app.preview.rows;
    if rows.is_empty() {
        return;
    }
    let match_rows: Vec<usize> = app.preview.groups.iter().map(|g| g.match_row).collect();
    if match_rows.is_empty() {
        return;
    }
    let sel = app.preview_state.selected();
    let next = match sel {
        None => {
            if forward { match_rows[0] } else { *match_rows.last().unwrap() }
        }
        Some(s) => {
            if forward {
                match_rows.iter().find(|&&r| r > s).copied().unwrap_or(match_rows[0])
            } else {
                match_rows.iter().rev().find(|&&r| r < s).copied().unwrap_or(*match_rows.last().unwrap())
            }
        }
    };
    app.preview_state.select(Some(next));
}

fn handle_preview_key(app: &mut App, key: KeyEvent) {
    if is_next_key(&key) {
        preview_select_match_row(app, true);
        return;
    }
    if is_prev_key(&key) {
        preview_select_match_row(app, false);
        return;
    }
    if is_top_key(&key) {
        if let Some(g) = app.preview.groups.first() {
            let r = g.match_row;
            app.preview_state.select(Some(r));
        }
        return;
    }
    if is_bottom_key(&key) {
        if let Some(g) = app.preview.groups.last() {
            let r = g.match_row;
            app.preview_state.select(Some(r));
        }
        return;
    }
    match key.code {
        KeyCode::Enter => {
            app.focus = Focus::ResultList;
        }
        KeyCode::Char('d') => {
            preview_delete_line(app);
        }
        KeyCode::Char('r') => {
            preview_replace_line(app);
        }
        _ => {}
    }
}

fn selected_preview_group(app: &App) -> Option<usize> {
    let sel = app.preview_state.selected()?;
    app.preview.rows.get(sel).map(|r| r.group)
}

fn after_group_removed(app: &mut App, file_path: &str) {
    // If the file has no match lines left, remove it and switch the preview
    // to the file now at the result-list selection index (clamped).
    let empty = app
        .results
        .files
        .iter()
        .find(|f| f.path == file_path)
        .map(|f| f.match_lines.is_empty())
        .unwrap_or(true);
    if empty {
        if let Some(pos) = app.results.files.iter().position(|f| f.path == file_path) {
            app.results.files.remove(pos);
        }
        if app.results.files.is_empty() {
            app.preview = crate::app::PreviewData::empty();
            app.preview_file = None;
            return;
        }
        let idx = app.result_state.selected().unwrap_or(0).min(app.results.files.len() - 1);
        app.result_state.select(Some(idx));
        let path = app.results.files[idx].path.clone();
        app.rebuild_preview(&path);
    } else {
        app.preview = build_preview(&app.results, file_path);
    }
}

fn preview_delete_line(app: &mut App) {
    let Some(group_idx) = selected_preview_group(app) else { return };
    let Some(group) = app.preview.groups.get(group_idx) else { return };
    let file_path = group.file_path.clone();
    let ln = group.line_number;
    if let Some(file) = app.results.files.iter_mut().find(|f| f.path == file_path) {
        if let Some(pos) = file.match_lines.iter().position(|&x| x == ln) {
            file.match_lines.remove(pos);
        }
        file.count = file.count.saturating_sub(1);
    }
    after_group_removed(app, &file_path);
}

fn preview_replace_line(app: &mut App) {
    let Some(group_idx) = selected_preview_group(app) else { return };
    let Some(group) = app.preview.groups.get(group_idx) else { return };
    let file_path = group.file_path.clone();
    let ln = group.line_number;
    let fs = crate::search::fs_path(&file_path, &app.project_root);
    let search = app.search_input.value().to_string();
    let replace = app.replace_input.value().to_string();
    crate::redux::thunk::process_line_replace::process_line_replace(
        &fs,
        ln,
        &search,
        &replace,
        app.search_mode,
        app.replace_mode,
    );
    app.notify_success("Line replacement completed successfully");
    if let Some(file) = app.results.files.iter_mut().find(|f| f.path == file_path) {
        if let Some(pos) = file.match_lines.iter().position(|&x| x == ln) {
            file.match_lines.remove(pos);
        }
        file.count = file.count.saturating_sub(1);
    }
    after_group_removed(app, &file_path);
}

fn process_replace_all(app: &mut App) {
    let search = app.search_input.value().to_string();
    let replace = app.replace_input.value().to_string();
    let files: Vec<String> = app.results.files.iter().map(|f| f.path.clone()).collect();
    for display in files {
        let fs = crate::search::fs_path(&display, &app.project_root);
        crate::redux::utils::replace_in_file(&fs, &search, &replace, app.search_mode, app.replace_mode);
    }
    app.reset_after_all_replace();
    app.notify_success("Search and replace completed successfully");
}
