            }
        }
    };
    app.preview_state.select(Some(next));
}

fn handle_preview_key(app: &mut App, key: KeyEvent) {
    if is_next_key(&key) {
        preview_select_match_row(app, true);
        return;
    }
    if is_prev_key(&key) {
        preview_select_match_row(app, false);
        return;
    }
    if is_top_key(&key) {
        if let Some(g) = app.preview.groups.first() {
            let r = g.match_row;
            app.preview_state.select(Some(r));
        }
