    }
    if is_bottom_key(&key) {
        if let Some(g) = app.preview.groups.last() {
            let r = g.match_row;
            app.preview_state.select(Some(r));
        }
        return;
    }
    match key.code {
        KeyCode::Enter => {
            app.focus = Focus::ResultList;
        }
        KeyCode::Char('d') => {
            preview_delete_line(app);
        }
        KeyCode::Char('r') => {
            preview_replace_line(app);
        }
        _ => {}
    }
}

fn selected_preview_group(app: &App) -> Option<usize> {
    let sel = app.preview_state.selected()?;
