mod app;
mod config;
mod errors;
mod events;
mod input;
mod json5;
mod modes;
mod redux;
mod render;
mod search;
mod terminal;

use errors::Report;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

pub fn relative_display_path(path: &Path) -> String {
    let Ok(cwd) = std::env::current_dir() else {
        return path.to_string_lossy().to_string();
    };
    pathdiff(&cwd, path)
}

fn pathdiff(from: &Path, to: &Path) -> String {
    let from_c: Vec<String> = from
        .components()
        .map(|c| c.as_os_str().to_string_lossy().to_string())
        .collect();
    let to_c: Vec<String> = to
        .components()
        .map(|c| c.as_os_str().to_string_lossy().to_string())
        .collect();
    // Root component yields "/" entries in both; find common prefix
    let mut i = 0;
    while i < from_c.len() && i < to_c.len() && from_c[i] == to_c[i] {
        i += 1;
    }
    let mut parts: Vec<String> = Vec::new();
    for _ in i..from_c.len() {
        // don't count the root separator component
        parts.push("..".to_string());
    }
    // Adjust: the first component of an absolute path is RootDir ("/");
    // it was consumed in the common prefix for both, so the number of ".."
    // should count only non-root remaining components. Recompute properly:
    let from_dirs: Vec<&std::path::Component> = from.components().collect();
    let to_dirs: Vec<&std::path::Component> = to.components().collect();
    let mut j = 0;
    while j < from_dirs.len() && j < to_dirs.len() && from_dirs[j] == to_dirs[j] {
        j += 1;
    }
    let mut out: Vec<String> = Vec::new();
    for _ in j..from_dirs.len() {
        out.push("..".to_string());
    }
    for c in &to_dirs[j..] {
        out.push(c.as_os_str().to_string_lossy().to_string());
    }
    let _ = parts;
    if out.is_empty() {
        ".".to_string()
    } else {
        out.join("/")
    }
}

fn main() {
    errors::install_panic_hook();
    let code = real_main();
    std::process::exit(code);
}

fn real_main() -> i32 {
    // ripgrep presence check happens before anything else (including
    // argument parsing).
    if Command::new("rg").arg("--version").output().is_err() {
        eprintln!("\x1b[31mError: ripgrep (rg) is not installed. Please install it to use serpl.\x1b[0m");
        errors::print_report(&Report::WithLocation(
            "ripgrep is not installed".to_string(),
            "src/main.rs:42:16",
        ));
        return 1;
    }

    let config_dir_display = config::config_dir().to_string_lossy().to_string();
    let version: &'static str = Box::leak(
        format!(
            "0.3.4- (2026-08-10)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {config_dir_display}"
        )
        .into_boxed_str(),
    );
    let matches = clap::Command::new("serpl")
        .about("A simple terminal UI for search and replace, ala VS Code")
        .version(version)
        .arg(
            clap::Arg::new("project-root")
                .short('p')
                .long("project-root")
                .value_name("PATH")
                .help("Path to the project root")
                .default_value("."),
        )
        .get_matches();
    let project_root = matches
        .get_one::<String>("project-root")
        .cloned()
        .unwrap_or_else(|| ".".to_string());

    let cfg = match config::Config::load() {
        Ok(c) => c,
        Err(msg) => {
            errors::print_report(&Report::Simple(msg));
            return 1;
