fn run_app(cfg: config::Config, project_root: String) -> io::Result<()> {
    terminal::enter_terminal()?;
    let backend = ratatui::backend::CrosstermBackend::new(io::stdout());
    let mut term = ratatui::Terminal::new(backend)?;
    let mut app = app::App::new(cfg, project_root);

    let result = event_loop(&mut term, &mut app);
    if let Err(e) = result {
        let _ = terminal::exit_terminal(&mut term);
        return Err(e);
    }
    terminal::exit_terminal(&mut term)
}

fn event_loop(
    term: &mut ratatui::Terminal<ratatui::backend::CrosstermBackend<io::Stdout>>,
    app: &mut app::App,
) -> io::Result<()> {
    let frame = Duration::from_millis(40);
    let mut first_poll = true;
    loop {
        term.draw(|f| render::draw(f, app))?;
        if app.should_quit {
            break;
        }
        if app.should_suspend {
            app.should_suspend = false;
            terminal::suspend();
            terminal::resume()?;
            term.clear()?;
            continue;
        }
        // Poll for events. The first poll surfaces terminal/read errors
        // (e.g. when there is no controlling terminal).
        let has = match crossterm::event::poll(frame) {
            Ok(h) => h,
            Err(e) => {
                if first_poll {
                    return Err(e);
                }
                false
            }
        };
        first_poll = false;
        if has {
            match crossterm::event::read() {
                Ok(crossterm::event::Event::Key(key)) => {
                    events::handle_key(app, key);
                }
                Ok(_) => {}
                Err(e) => return Err(e),
            }
            // Drain any immediately available extra key events so multi
            // character bursts (e.g. pasted text) are processed before the
            // next search, matching the reference batching.
            loop {
                match crossterm::event::poll(Duration::from_millis(0)) {
                    Ok(true) => {
                        if let Ok(crossterm::event::Event::Key(key)) = crossterm::event::read() {
                            events::handle_key(app, key);
                            if app.should_quit {
                                break;
                            }
                        }
                    }
                    _ => break,
                }
            }
        }
        if app.needs_search {
            app.do_search();
        }
        app.prune_notifications();
    }
    Ok(())
}
