        buf.set_stringn(start as u16, area.y, text, area.width as usize, style);
    } else {
        let skip = (left - start) as usize;
        if skip < text.len() {
            buf.set_stringn(left as u16, area.y, &text[skip..], (end - left) as usize, style);
        }
    }
}

fn wrap_help_text(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![String::new()];
    }
    // Greedy word wrap that keeps the breaking space as the first character
    // of the next line (matching the reference's older text wrapper).
    let mut lines: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut word = String::new();
    let mut pending_space = false;
    let flush_word = |lines: &mut Vec<String>, current: &mut String, word: &mut String, pending_space: &mut bool| {
        if word.is_empty() {
            return;
        }
        let space_w = if *pending_space && !current.is_empty() { 1 } else { 0 };
        if !current.is_empty() && current.len() + space_w + word.len() > width {
            let mut done = std::mem::take(current);
            lines.push(std::mem::take(&mut done));
            if *pending_space {
                current.push(' ');
            }
        } else if *pending_space && !current.is_empty() {
            current.push(' ');
        }
        // hard-split very long words
        while current.len() + word.len() > width {
            let avail = width - current.len();
            if avail == 0 {
                lines.push(std::mem::take(current));
                continue;
            }
            let part: String = word.drain(..word.char_indices().nth(avail).map(|(i, _)| i).unwrap_or(word.len())).collect();
            current.push_str(&part);
            lines.push(std::mem::take(current));
        }
        current.push_str(word);
        word.clear();
        *pending_space = false;
    };
    for c in text.chars() {
        if c == ' ' {
            flush_word(&mut lines, &mut current, &mut word, &mut pending_space);
            if current.is_empty() && lines.is_empty() {
                current.push(' ');
            } else {
                pending_space = true;
            }
        } else {
            word.push(c);
        }
    }
    flush_word(&mut lines, &mut current, &mut word, &mut pending_space);
    lines.push(current);
    lines
}
